### BRFSS & YRBS SO Analyses

# This script's code uses the SO analytic objects generated by "SOGI_04_SO prepare"
### and produces results (e.g. plots, statistical analyses)

### Prepare workspace ----- 
# clear environment
rm(list = ls())

# packages
source("SOGI_00_packages.R")

# define functions
tableNA <- function(x, ...){
   table(x, useNA = "ifany", ...)  
}

# call in data
brfss_dat <- readRDS("data - clean/brfss_final.rds")
yrbs_dat <- readRDS("data - clean/yrbs_final.rds")
combined <- readRDS("data - clean/combined.rds")
so_props_A <- readRDS("data - clean/so_props_A.rds")
so_props_F <- readRDS("data - clean/so_props_F.rds")
so_props_M <- readRDS("data - clean/so_props_M.rds")

# generate objects needed for analyses
so_values <- levels(as.factor(combined$so_new))

comb_cohort_n <- length(min(combined$cohort):max(combined$cohort))
comb_period_n <- length(min(combined$year):max(combined$year))
comb_cohort_v <- min(combined$cohort):max(combined$cohort) 
comb_period_v <- min(combined$year):max(combined$year)

com_yrs <- c(2015, 2017, 2019, 2021)
age_labels <- seq(15, 80, 5)
coh_labels <- comb_cohort_v[comb_cohort_v %% 5 == 0]


# * Plots & Visual Analyses -------
# * * Female plots, pairs of by SO, plot A = 

# plotting objects
ids <- c("report being straight", "report being lesbian/gay", 
         "report being bisexual", "provide some other response", 
         "decline to report their SO")
cols <- rainbow_hcl(comb_cohort_n+1)[1:comb_cohort_n]
cols_pds <- rainbow_hcl(comb_period_n+1)[1:comb_period_n] 
n_ids <- length(ids)

lwd <- 0.3
cex <- 0.3
loess.lwd <- 1.5
cex.axis <- 1.8
lwd.ticks <- 0.5
cex.axis.labs <- 0.6
cex.main <- 0.8
yline <- 4
xline <- 4
loess.span <- 0.5

heights <- c(0.5+3.5*50/50, 0.5+3.5*25/50, 0.5+3.5*25/50, 
             0.5+3.5*25/50, 0.5+3.5*25/50)

for (id in 1:n_ids) {

#   filename <- paste0("plots/SOplots_", id, ".pdf")
#   pdf(filename,
#       width = 6.5,
#       height = sum(sapply(1:5, function(x) (id==x)*heights[x])))
   
#  filename <- paste0("plots/SOplots_", id, ".bmp")
#  bmp(filename,
   filename <- paste0("plots/SOplots_", id, ".png")
   png(filename,
           units = "in", res=300,
       width = 6.5,
      # height = sum(sapply(1:5, function(x) (id==x)*heights[x])))
       height = 6.5)

#   mylayout <- matrix(c(
#      1,1,1,2,2,2,5,3,3,3,4,4,4,
#      1,1,1,2,2,2,5,3,3,3,4,4,4,
#      1,1,1,2,2,2,5,3,3,3,4,4,4),
#      byrow = TRUE, nrow = 3
#   )
   
   lreps <- 15
   
   mylayout <- matrix(c(
         rep(c(rep(1,lreps),5,rep(2,lreps)), lreps),
         rep(5, 2*lreps+1), 
         rep(5, 2*lreps+1), 
         rep(5, 2*lreps+1), 
         rep(5, 2*lreps+1), 
         rep(c(rep(3,lreps),5,rep(4,lreps)), lreps)),
         byrow = TRUE, nrow = 2*lreps+4
      )

      layout(mylayout)

   par(mar = c(0,0,0,0), 
       oma = c(6,7,4,2),
       cex = cex,
       lwd = lwd,
       tcl = -0.2,
       mgp=c(3,1,0))
   
   plot(x= comb_period_v[1] - 
           comb_cohort_v[which(!is.na(so_props_F[,1,id]))],
        y=so_props_F[,1,id] %>% na.rm,
        type = "o",
        col = cols_pds[1],
        xlim = c(13, 80),
        ylim = (id==1)*c(50, 100) + 
               (id!=1)*c( 0,  25),
        xaxs="i", yaxs="i",
        axes=FALSE
   )
   
   temp_x <- comb_period_v[1]-comb_cohort_v[which(!is.na(so_props_F[,1,id]))]
   temp <- loess((so_props_F[,1,id] %>% na.rm) ~ temp_x, span=loess.span)
   lines(temp$x, temp$fitted, col=cols_pds[1], lwd=loess.lwd)
   
   for(period in 2:length(comb_period_v)) {
      lines(x= comb_period_v[period] -
               comb_cohort_v[which(!is.na(so_props_F[,period,id]))],
            y=so_props_F[,period,id] %>% na.rm,
            type = "o",
            col = cols_pds[period])
      temp_x <- comb_period_v[period]-comb_cohort_v[which(!is.na(so_props_F[,period,id]))]
      temp <- loess((so_props_F[,period,id] %>% na.rm) ~ temp_x, span=loess.span)
      lines(temp$x, temp$fitted, col=cols_pds[period], lwd=loess.lwd)
   }
   axis(1, col = "grey40", col.axis = "grey20", 
        at = age_labels, cex.axis=cex.axis, lwd=0, lwd.ticks=lwd.ticks)
   axis(2, col = "grey40", col.axis = "grey20", 
        at = seq(0, 100, 5), cex.axis=cex.axis, lwd=0, lwd.ticks=lwd.ticks)
   box(col = "grey60")
   mtext("Age", side = 1, outer = FALSE, cex = cex.axis.labs, line = xline,
         col = "grey20")
   mtext(paste0("% of respondents who ", ids[id]), side = 2, outer = FALSE, cex = cex.axis.labs, 
         line = yline, col = "grey20")
   mtext("Female", side = 3, outer = FALSE, cex = cex.main, 
         col = "grey20", line=0.5)
   mtext("a", side = 3, line = -2, adj = 0.03, cex = 0.7,
         col = "grey40")   
   
   plot(x= comb_period_v[1] - 
           comb_cohort_v[which(!is.na(so_props_M[,1,id]))],
        y=so_props_M[,1,id] %>% na.rm,
        type = "o",
        col = cols_pds[1],
        xlim = c(13, 80),
        ylim = (id==1)*c(50, 100) + 
               (id!=1)*c( 0,  25),
        xlab = "Respondent age",
        xaxs="i", yaxs="i",
        axes=FALSE
   )

   temp_x <- comb_period_v[1]-comb_cohort_v[which(!is.na(so_props_M[,1,id]))]
   temp <- loess((so_props_M[,1,id] %>% na.rm) ~ temp_x, span=loess.span)
   lines(temp$x, temp$fitted, col=cols_pds[1], lwd=loess.lwd)
   
   for(period in 2:length(comb_period_v)) {
      lines(x= comb_period_v[period] -
               comb_cohort_v[which(!is.na(so_props_M[,period,id]))],
            y=so_props_M[,period,id] %>% na.rm,
            type = "o",
            col = cols_pds[period])
      temp_x <- comb_period_v[period]-comb_cohort_v[which(!is.na(so_props_M[,period,id]))]
      temp <- loess((so_props_M[,period,id] %>% na.rm) ~ temp_x, span=loess.span)
      lines(temp$x, temp$fitted, col=cols_pds[period], lwd=loess.lwd)
   }
   axis(1, col = "grey40", col.axis = "grey20", 
        at = age_labels, cex.axis=cex.axis, lwd=0, lwd.ticks=lwd.ticks)
   box(col = "grey60")
   mtext("Age", side = 1, outer = FALSE, cex = cex.axis.labs, line = xline,
         col = "grey20")
   mtext("Male", side = 3, outer = FALSE, cex = cex.main, 
         col = "grey20", line=0.5)
   mtext("b", side = 3, line = -2, adj = 0.03, cex = 0.7,
         col = "grey40")   
   
   plot(x= comb_cohort_v[which(!is.na(so_props_F[,1,id]))],
        y=so_props_F[,1,id] %>% na.rm,
        type = "o",
        col = cols_pds[1],
#        xlim= c(comb_cohort_v[comb_cohort_n],comb_cohort_v[1]),
        xlim= c(comb_cohort_v[1],comb_cohort_v[comb_cohort_n]),
        ylim = (id==1)*c(50, 100) + 
               (id!=1)*c( 0,  25),
        xlab = "Birth cohort",
        xaxs="i", yaxs="i",
        axes=FALSE
   )
   
   temp <- loess((so_props_F[,1,id] %>% na.rm) ~
                    comb_cohort_v[which(!is.na(so_props_F[,1,id]))], span=loess.span)
   lines(temp$x, temp$fitted, col=cols_pds[1], lwd=loess.lwd)
   
   for(period in 2:length(comb_period_v)) {
      lines(x= comb_cohort_v[which(!is.na(so_props_F[,period,id]))],
            y=so_props_F[,period,id] %>% na.rm,
            type = "o",
            col = cols_pds[period])
      temp <- loess((so_props_F[,period,id] %>% na.rm) ~
                       comb_cohort_v[which(!is.na(so_props_F[,period,id]))], span=loess.span)
      lines(temp$x, temp$fitted, col=cols_pds[period], lwd=loess.lwd)
      
   }
   axis(1, col = "grey40", col.axis = "grey20", 
        at = coh_labels, cex.axis=cex.axis, lwd=0, lwd.ticks=lwd.ticks)
   axis(2, col = "grey40", col.axis = "grey20", 
        at = seq(0, 100, 5), cex.axis=cex.axis, lwd=0, lwd.ticks=lwd.ticks)
   box(col = "grey60")
   mtext("Birth cohort", side = 1, outer = FALSE, cex = cex.axis.labs, line = xline,
         col = "grey20")
   mtext(paste0("% of respondents who ", ids[id]), side = 2, outer = FALSE, cex = cex.axis.labs, 
         line = yline, col = "grey20")
   mtext("Female", side = 3, outer = FALSE, cex = cex.main, 
         col = "grey20", line=0.5)
   mtext("c", side = 3, line = -2, adj = 0.03, cex = 0.7,
         col = "grey40")   
   
   plot(x= comb_cohort_v[which(!is.na(so_props_M[,1,id]))],
        y=so_props_M[,1,id] %>% na.rm,
        type = "o",
        col = cols_pds[1],
#        xlim= c(comb_cohort_v[comb_cohort_n],comb_cohort_v[1]),
        xlim= c(comb_cohort_v[1],comb_cohort_v[comb_cohort_n]),
        ylim = (id==1)*c(50, 100) + 
               (id!=1)*c( 0,  25),
        xaxs="i", yaxs="i",
        axes = FALSE
   )

   temp <- loess((so_props_M[,1,id] %>% na.rm) ~
                    comb_cohort_v[which(!is.na(so_props_M[,1,id]))], span=loess.span)
   lines(temp$x, temp$fitted, col=cols_pds[1], lwd=loess.lwd)

   for(period in 2:length(comb_period_v)) {
      lines(x= comb_cohort_v[which(!is.na(so_props_M[,period,id]))],
            y=so_props_M[,period,id] %>% na.rm,
            type = "o",
            col = cols_pds[period])
      temp <- loess((so_props_M[,period,id] %>% na.rm) ~
                       comb_cohort_v[which(!is.na(so_props_M[,period,id]))], span=loess.span)
      lines(temp$x, temp$fitted, col=cols_pds[period], lwd=loess.lwd)
   }
   axis(1, col = "grey40", col.axis = "grey20", 
        at = coh_labels, cex.axis=cex.axis, lwd=0, lwd.ticks=lwd.ticks)
   
   #mtext(letters[i], side = 3, line = -1, adj = 0.1, cex = 0.6,
   #      + col = "grey40")
   box(col = "grey60")
   mtext("Birth cohort", side = 1, outer = FALSE, cex = cex.axis.labs, line = xline,
         col = "grey20")
   mtext("Male", side = 3, outer = FALSE, cex = cex.main, 
         col = "grey20", line=0.5)
   mtext("d", side = 3, line = -2, adj = 0.02, cex = 0.7,
         col = "grey40")   
   
   legend(c("bottom"[id==1],"top"[id>1]),
       inset = 0.05,
       border = "black",
       title = "Period (survey year)",
       legend = c(seq(min(comb_period_v), max(comb_period_v))),
       col = cols_pds[seq(1, length(comb_period_v))],
       lwd = loess.lwd,
       lty = 1.5,
       cex = 1.5,
       ncol = 2,
       bg="gray99")
   
   plot(1,1, col="white" ,axes= F)
   dev.off()
}

